def line_transform(g):
    h,w=len(g),len(g[0]); out=[r[:] for r in g]
    src=[(r,c) for r in range(h) for c in range(w) if g[r][c]==2]
    if not src: return out
    sr,sc=src[0]
    # select horizontal 8-rails
    bars=[r for r in range(h) if sum(v==8 for v in g[r])>=max(3,w//2)]
    if not bars: return out
    exits=[]
    for r in bars:
        holes=[c for c,v in enumerate(g[r]) if v!=8]
        # border rails: select outer openings only
        xs=sorted(set([holes[0],holes[-1]])) if holes else []
        exits.append(xs)
    def paint(r,c):
        if 0<=r<h and 0<=c<w and g[r][c]!=8: out[r][c]=2
    def interval(r, cols):
        if cols:
            for c in range(min(cols),max(cols)+1): paint(r,c)
    # if source lies before first rail (most common)
    if sr<bars[0]:
        first=bars[0]; X=exits[0]
        if X:
            interval(first-1,[sc]+X)
            for c in X: paint(first,c)
        for i in range(len(bars)-1):
            r0,r1=bars[i],bars[i+1]; A=exits[i]; B=exits[i+1]; gap=r1-r0-1
            for c in A: paint(r0+1,c)
            if gap==1:
                interval(r0+1, A+B)
            elif gap>=2:
                # intermediate rows continue active exits; terminal row joins exits
                for rr in range(r0+2,r1):
                    if rr==r1-1 and len(B)==1 and len(A)>1:
                        interval(rr,range(w))
                    elif rr==r1-1:
                        interval(rr,A+B)
                    else:
                        for c in A: paint(rr,c)
            for c in B: paint(r1,c)
        last=bars[-1]
        for c in exits[-1]:
            for r in range(last+1,h): paint(r,c)
    return out
